mapper.select:
SELECT id, owner_id, source_system, source_order_no, request_digest, status, strategy_version, active_attempt_id, version
FROM fulfillment_order
WHERE enterprise_id=#{enterpriseId}
AND source_system=#{sourceSystem}
AND source_order_no=#{sourceOrderNo} FOR UPDATE

mapper.update:
UPDATE fulfillment_order
SET active_attempt_id=#{attemptId}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{orderId}
AND version=#{version}
AND (active_attempt_id IS NULL OR active_attempt_id=#{expectedActive})

mapper.select:
SELECT source_line_id, sku_id, requested_qty, base_unit, min_remaining_days
FROM fulfillment_line
WHERE enterprise_id=#{enterpriseId}
AND fulfillment_id=#{fulfillmentId}
ORDER BY source_line_id FOR UPDATE

mapper.update:
UPDATE allocation_attempt
SET launch_owner=#{owner}, launch_lease_until=#{leaseUntil}, launch_epoch=launch_epoch+1, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{id}
AND xid IS NULL
AND launch_epoch=#{epoch}
AND version=#{version}
AND state IN ('PLANNED','TCC_STARTING')
AND (launch_owner IS NULL OR launch_owner=#{owner})

UPDATE allocation_attempt
SET xid=#{xid}, xid_bound_at=#{now}, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{id}
AND xid IS NULL
AND launch_owner=#{owner}
AND launch_epoch=#{epoch}
AND state='TCC_STARTING'

UPDATE allocation_attempt
SET tc_observed_status=#{status}, tc_terminal_evidence=#{evidence}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{id}

UPDATE allocation_attempt
SET state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{id}
AND state=#{expected}

mapper.select:
SELECT id, warehouse_id, reservation_id, xid, branch_id, action_name, route_epoch, observed_branch_state, state, last_error, confirmed_version, confirmed_allocation_id, version
FROM allocation_participant
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
ORDER BY warehouse_id FOR UPDATE

mapper.update:
UPDATE allocation_participant SET confirmed_allocation_id=#{allocationId},version=version+1,updated_at=#{now}
WHERE enterprise_id=#{enterpriseId} AND attempt_id=#{attemptId} AND warehouse_id=#{warehouseId}
AND confirmed_allocation_id IS NULL

UPDATE allocation_participant
SET state=#{state}, observed_branch_state=#{state}, confirmed_version=#{confirmedVersion}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
AND warehouse_id=#{warehouseId}

UPDATE allocation_participant
SET xid=#{xid}, branch_id=#{branchId}, action_name=#{actionName}, reservation_id=#{reservationId}, route_epoch=#{routeEpoch}, observed_branch_state=#{branchState}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
AND warehouse_id=#{warehouseId}
AND (xid IS NULL OR (xid=#{xid}
AND branch_id=#{branchId}
AND action_name=#{actionName}
AND reservation_id=#{reservationId}
AND route_epoch=#{routeEpoch}))

UPDATE allocation_launch
SET xid=#{xid}, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
AND launch_epoch=#{epoch}
AND executor_id=#{executorId}
AND xid IS NULL

mapper.select:
SELECT id, attempt_id, launch_epoch, executor_id, xid, state, cleanup_state, error_code, cleanup_terminal_evidence, version
FROM allocation_launch
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
AND launch_epoch=#{epoch} FOR UPDATE

mapper.update:
UPDATE allocation_launch
SET state=#{state}, cleanup_state=#{cleanup}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
AND launch_epoch=#{epoch}
AND state='CLAIMED'

UPDATE allocation_launch
SET xid=#{xid}, state=#{state}, cleanup_state=#{cleanup}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
AND launch_epoch=#{epoch}
AND xid IS NULL
AND state IN ('CLAIMED','UNKNOWN')

UPDATE allocation_launch
SET cleanup_state=#{cleanup}, error_code=#{errorCode}, cleanup_terminal_evidence=#{evidence}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
AND launch_epoch=#{epoch}
AND cleanup_state IN ('NONE','PENDING')

UPDATE allocation_attempt
SET launch_owner=#{owner}, launch_lease_until=#{leaseUntil}, launch_epoch=launch_epoch+1, state=#{state}, version=version+1, updated_at=#{now}
WHERE enterprise_id=#{enterpriseId}
AND id=#{id}
AND xid IS NULL
AND launch_epoch=#{epoch}
AND version=#{version}
AND state IN ('PLANNED','TCC_STARTING')
AND EXISTS (SELECT 1
FROM allocation_launch l
WHERE l.enterprise_id=#{enterpriseId}
AND l.attempt_id=#{id}
AND l.launch_epoch=#{epoch}
AND l.state='UNKNOWN')
AND NOT EXISTS (SELECT 1
FROM allocation_participant p
WHERE p.enterprise_id=#{enterpriseId}
AND p.attempt_id=#{id}
AND p.reservation_id IS NOT NULL)

mapper.select:
SELECT p.warehouse_id, p.reservation_id, l.order_line_id, l.sku_id, l.qty, l.base_unit
FROM allocation_participant p JOIN participant_line l ON l.enterprise_id=p.enterprise_id
AND l.participant_id=p.id
WHERE p.enterprise_id=#{enterpriseId}
AND p.attempt_id=#{attemptId}
ORDER BY p.warehouse_id, l.order_line_id

SELECT event_id,operation_id,payload,delivery_payload FROM fulfillment_outbox
WHERE enterprise_id=#{enterpriseId} AND attempt_id=#{attemptId}
AND warehouse_id=#{warehouseId} AND event_type=#{eventType} FOR UPDATE

SELECT COUNT(*)
FROM fulfillment_outbox
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}

SELECT id, owner_id, source_system, source_order_no, status, strategy_version, active_attempt_id, version, created_at
FROM fulfillment_order
WHERE enterprise_id=#{enterpriseId}

    AND (created_at < #{page.time} OR (created_at = #{page.time} AND id < #{page.id}))

ORDER BY created_at DESC, id DESC
LIMIT #{page.fetchLimit}

SELECT id, warehouse_id, reservation_id, xid, branch_id, observed_branch_state, state, confirmed_version
FROM allocation_participant
WHERE enterprise_id=#{enterpriseId}
AND attempt_id=#{attemptId}
ORDER BY warehouse_id
